WITH expected(code,unit,tower,capacity,bedrooms,bathrooms,parking_spots,parking_box) AS (VALUES ('IMP-00033','506','Bloco B',2,1,1,1,'66'),('IMP-00027','101','Residencial Platános',2,1,1,1,'101'),('IMP-00026','403','A',3,1,1,1,'13'),('IMP-00034','205',NULL,4,2,3,1,'26'),('IMP-00022','406','Torre B',6,2,2,1,'30'),('IMP-00009','105','A - Verona',4,2,2,1,'5'),('IMP-00018','103','B - Veneza',4,1,1,1,'03'),('IMP-00025','104','B - Veneza',4,2,3,1,'04'),('IMP-00019','203','C - Padova',2,1,1,1,'9'),('IMP-00015','306','D - Treviso',4,1,2,1,'18'),('IMP-00028','202','E - Vivenda',4,2,2,1,'08'),('IMP-00029','402','E - Vivenda',4,2,2,1,'20'),('IMP-00031','102','G - Garda',2,1,1,1,'02'),('IMP-00030','303','G - Garda',4,2,2,1,'15'),('IMP-00008','203','H - Vicenza',4,2,2,1,'09'),('IMP-00020','403','H - Vicenza',4,1,1,1,'21'),('IMP-00032','101','I - Panzano',4,2,2,1,'01'),('IMP-00021','403','I - Panzano',4,1,1,1,'21'),('IMP-00035','306',NULL,2,1,1,1,'18')) SELECT e.code,1 / CASE WHEN p.id IS NOT NULL AND p.unit=e.unit AND (e.tower IS NULL OR p.tower=e.tower) AND p.capacity=e.capacity AND p.bedrooms=e.bedrooms AND d.bathrooms=e.bathrooms AND d.parking_spots=e.parking_spots AND d.parking_box=e.parking_box THEN 1 ELSE 0 END AS passed FROM expected e LEFT JOIN public.implementation_projects p USING(code) LEFT JOIN public.implementation_property_details d ON d.implementation_id=p.id ORDER BY e.code;